window.kbPageData["views/entry/k-a64c87b891ac4752"] = {"key":"entry/k-a64c87b891ac4752","state":{"route":"entry/k-a64c87b891ac4752"},"node":{"id":"k-a64c87b891ac4752","mode":"k","title":"增长幅度与构成比重","type":"概念与词义","domain":"统计","reading":"","intro":"","priority":100,"aliases":["增长幅度与构成比重的区别"],"qs":["江苏 2025 C类 行测#96"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"增长幅度反映同一指标在两个时期之间增加了多少，若以百分比表示，则以基期数值为分母。构成比重是同一统计范围内某一部分占总体的比例，以总体数值为分母。","review":{"definition":"增长幅度反映同一指标在两个时期之间增加了多少，若以百分比表示，则以基期数值为分母。构成比重是同一统计范围内某一部分占总体的比例，以总体数值为分母。","explanation":"第96题中，甲用折叠屏手机销量连续多年保持两位数增长来预测研发趋势，乙用其销量仅占手机整体销量的1.6%来质疑增加投入的必要性。销量基数较小时，增速高与市场份额小可以同时成立。C项同样从数量增长转向相对比例：错别字检出量随出版总量增加而上升，检出率却维持在万分之一左右，乙据此质疑增员的必要性。B项则是把张明的提分幅度与全班平均提分幅度比较，两边衡量的都是增幅。","references":[],"evidence":"仍只占手机整体销量的1.6%","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 C类 行测#96":{"paper":"江苏 2025 C类 行测","n":96,"mod":"判断推理","src":["ffc394a1c160f331ec57.pdf",20],"asrc":["d1de3b437151c05b769e.pdf",29],"card":"427696fff9e8e5df947f9bf5","links":[{"id":"k-a64c87b891ac4752","role":"解题依据","why":"增长幅度比较不同时期的数值，构成比重比较部分与整体，这一区别决定两方使用的证据是否对应。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a64c87b891ac4752":[["江苏 2025 C类 行测#96"]]}};
